package universal_test
import("context";"os";"path/filepath";"testing";"time";"swypik-os/core/autogenesis";"swypik-os/core/hal";"swypik-os/installer/universal")
func TestUniversalInstallerPC(t *testing.T){halMgr:=hal.NewManager();synth:=autogenesis.NewSynthesizer("");eng:=universal.NewInstallerEngine(halMgr,synth);ctx,cancel:=context.WithTimeout(context.Background(),2*time.Second);defer cancel();env,err:=eng.ProbeTarget(ctx);if err!=nil{t.Fatal(err)};if env.PlatformType!=universal.PlatformPC{t.Errorf("Expected PC, got %s",env.PlatformType)};plan:=eng.GenerateAdaptationPlan(env);if plan.TargetProfile!="SwypikOS-Desktop-SpatialLuxury"{t.Error(plan.TargetProfile)};tempDir:=t.TempDir();if err:=eng.Deploy(ctx,tempDir,env,plan);err!=nil{t.Fatal(err)};if _,err:=os.Stat(filepath.Join(tempDir,"swypik_deployment_manifest.json"));err!=nil{t.Fatal(err)}}
func TestUniversalInstallerRobotAndVehicle(t *testing.T){halRobot:=hal.NewManager();halRobot.AttachRobotSimulation("Swypik Robotic Arm",6);synth:=autogenesis.NewSynthesizer("");engRobot:=universal.NewInstallerEngine(halRobot,synth);ctx,cancel:=context.WithTimeout(context.Background(),2*time.Second);defer cancel();envRobot,err:=engRobot.ProbeTarget(ctx);if err!=nil{t.Fatal(err)};if envRobot.PlatformType!=universal.PlatformRobot{t.Error(envRobot.PlatformType)};planRobot:=engRobot.GenerateAdaptationPlan(envRobot);if planRobot.SafetyGovernorMode!="ROBOTICS_ESTOP_ARMED"{t.Error(planRobot.SafetyGovernorMode)};halVehicle:=hal.NewManager();halVehicle.AttachVehicleSimulation("Electric Vehicle Gateway","1FA6P8CF5H123456");engVehicle:=universal.NewInstallerEngine(halVehicle,synth);envVehicle,err:=engVehicle.ProbeTarget(ctx);if err!=nil{t.Fatal(err)};if envVehicle.PlatformType!=universal.PlatformVehicle{t.Error(envVehicle.PlatformType)};planVehicle:=engVehicle.GenerateAdaptationPlan(envVehicle);if planVehicle.SafetyGovernorMode!="AUTOMOTIVE_CRITICAL_WATCHDOG"{t.Error(planVehicle.SafetyGovernorMode)}}
func TestUserDataPartitionMapping(t *testing.T){eng:=universal.NewInstallerEngine(nil,nil);workspace:=t.TempDir();profile:=t.TempDir();if err:=os.MkdirAll(filepath.Join(profile,"Documents"),0700);err!=nil{t.Fatal(err)};if err:=os.WriteFile(filepath.Join(profile,"Documents","fixture.txt"),[]byte("owned test fixture"),0600);err!=nil{t.Fatal(err)};mapping,err:=eng.MapUserDataPartitions(profile,workspace);if err!=nil{t.Fatal(err)};if !mapping.ZeroLossVerified||len(mapping.MappedPartitions)==0{t.Fatal("fixture mapping was not verified")};if _,err:=os.Stat(filepath.Join(workspace,"swypik_user_mounts.json"));err!=nil{t.Fatal(err)}}
